			cf.DesiredRoles = "*"
		}
	}

	if cf.DesiredRoles != "" {
		fmt.Println("") // visually separate access request output
		if err := executeAccessRequest(cf); err != nil {
			tc.Logout()
			utils.FatalError(err)
		}
	}

